<script setup>
import { DateTime } from 'luxon'
import { STATUSES, STATUS_LABELS, SOURCES } from '#shared/constants/index.js'
import { money, today } from '#shared/utils/format.js'
const props=defineProps({type:{type:String,default:'orders'}})
const filters=reactive({from:DateTime.fromISO(today()).startOf('month').toISODate(),to:today(),locationId:'',therapistId:'',serviceId:'',status:'',source:''})
const query=computed(()=>Object.fromEntries(Object.entries(filters).filter(([,v])=>v!=='')))
const {data,refresh,error}=await useFetch('/api/reports',{query})
const {data:locations}=await useFetch('/api/locations',{default:()=>[]})
const {data:therapists}=await useFetch('/api/therapists',{default:()=>[]})
const {data:services}=await useFetch('/api/services',{default:()=>[]})
const tab=ref(props.type)
const revenueCards=computed(()=>[{label:'Gross revenue',value:data.value?.summary.grossRevenue},{label:'Diskon',value:data.value?.summary.discount},{label:'Transport fee',value:data.value?.summary.transportFee},{label:'Pajak',value:data.value?.summary.tax},{label:'Refund',value:data.value?.summary.refund},{label:'Net collected',value:data.value?.summary.netRevenue},{label:'Bagian owner',value:data.value?.summary.ownerShare},{label:'Bagian admin',value:data.value?.summary.adminShare},{label:'Bagian therapist',value:data.value?.summary.therapistShare},{label:'Menunggu layanan selesai',value:data.value?.summary.pendingShare}])
const page=ref(1);watch([query,tab],()=>page.value=1)
const tableRows=computed(()=>tab.value==='locations'?data.value?.locations||[]:tab.value==='therapists'?data.value?.therapists||[]:data.value?.orders||[])
const visible=computed(()=>tableRows.value.slice((page.value-1)*10,page.value*10))
function download(){const table=tab.value==='therapists'?data.value.therapists:tab.value==='locations'?data.value.locations:data.value.orders.map(o=>({orderNumber:o.orderNumber,customer:o.customerName,date:o.bookingDate,time:o.bookingTime,location:o.locationName,status:o.orderStatus,total:o.total,paymentStatus:o.paymentStatus,ownerShare:o.revenueShare?.ownerAmount||0,adminShare:o.revenueShare?.adminAmount||0,therapistShare:o.revenueShare?.therapistAmount||0}));if(!table.length)return;const keys=Object.keys(table[0]);const escape=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const csv='\uFEFF'+[keys.map(escape).join(','),...table.map(r=>keys.map(k=>escape(r[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`serene-${tab.value}-${filters.from}-${filters.to}.csv`;a.click();URL.revokeObjectURL(url)}
</script><template><div><LayoutPageHeader title="Reports & insights" description="Pahami performa pelayanan dan keuangan Anda." eyebrow="BUSINESS INSIGHTS"><UiButton variant="secondary" :disabled="!tableRows.length" @click="download"><UiIcon name="download" :size="17" />Export CSV</UiButton></LayoutPageHeader><div class="summary-tabs"><button v-for="[key,label] in [['orders','Orders'],['revenue','Revenue'],['therapists','Therapists'],['locations','Locations']]" :key="key" :class="{active:tab===key}" @click="tab=key">{{ label }}</button></div><section class="panel report-filters"><label>Dari tanggal<input v-model="filters.from" type="date" required /></label><label>Sampai tanggal<input v-model="filters.to" type="date" required :min="filters.from" /></label><label>Lokasi<select v-model="filters.locationId"><option value="">Semua lokasi</option><option v-for="l in locations" :key="l.id" :value="l.id">{{ l.name }}</option></select></label><label>Therapist<select v-model="filters.therapistId"><option value="">Semua therapist</option><option v-for="t in therapists" :key="t.id" :value="t.id">{{ t.name }}</option></select></label><label>Layanan<select v-model="filters.serviceId"><option value="">Semua layanan</option><option v-for="s in services" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label>Status<select v-model="filters.status"><option value="">Semua status</option><option v-for="s in STATUSES" :key="s" :value="s">{{ STATUS_LABELS[s] }}</option></select></label><label>Sumber<select v-model="filters.source"><option value="">Semua sumber</option><option v-for="s in SOURCES" :key="s" :value="s">{{ s }}</option></select></label></section><p v-if="error" class="error-message">{{ error.data?.data?.message||error.data?.statusMessage }}</p><div v-if="tab==='revenue'" class="finance-metrics revenue-metrics"><div v-for="card in revenueCards" :key="card.label" class="metric-card"><span>{{ card.label }}</span><strong class="metric-value">{{ money(card.value) }}</strong></div></div><div v-else class="finance-metrics"><div class="metric-card"><span>Total orders</span><strong class="metric-value">{{ data?.summary.orders||0 }}</strong></div><div class="metric-card"><span>Treatment selesai</span><strong class="metric-value">{{ data?.summary.completed||0 }}</strong></div><div class="metric-card"><span>Pembayaran bersih</span><strong class="metric-value">{{ money(data?.summary.netRevenue) }}</strong></div></div><p class="form-hint mb-4">Rentang laporan mengikuti tanggal booking. Revenue dihitung dari treatment selesai; net collected dari pembayaran sukses setelah refund. Pembagian mengikuti formula yang dikunci per order, dengan transport dan pajak terpisah.</p><section class="panel"><div class="panel-heading"><h2>{{ {orders:'Order report',revenue:'Transaksi treatment',therapists:'Therapist performance',locations:'Location performance'}[tab] }}</h2><span class="count">{{ tableRows.length }}</span></div><OrderTable v-if="['orders','revenue'].includes(tab)" :orders="visible" /><div v-else class="table-wrap"><table v-if="tab==='therapists'"><thead><tr><th>Therapist</th><th>Assigned</th><th>Accepted</th><th>Rejected</th><th>Completed</th><th>Jam layanan</th><th>Revenue layanan</th><th>Bagian therapist</th></tr></thead><tbody><tr v-for="t in visible" :key="t.id"><td><strong>{{ t.name }}</strong></td><td>{{ t.assigned }}</td><td>{{ t.accepted }}</td><td>{{ t.rejected }}</td><td>{{ t.completed }}</td><td>{{ t.hours.toFixed(1) }} jam</td><td>{{ money(t.revenue) }}</td><td>{{ money(t.commission) }}</td></tr></tbody></table><table v-else><thead><tr><th>Lokasi</th><th>Orders</th><th>Completed</th><th>Cancelled</th><th>Revenue</th><th>Average order</th><th>Utilization</th></tr></thead><tbody><tr v-for="l in visible" :key="l.id"><td><strong>{{ l.name }}</strong></td><td>{{ l.orders }}</td><td>{{ l.completed }}</td><td>{{ l.cancelled }}</td><td>{{ money(l.revenue) }}</td><td>{{ money(l.average) }}</td><td>{{ l.utilization.toFixed(1) }}%</td></tr></tbody></table><UiEmptyState v-if="!tableRows.length" /></div><UiPagination v-model:page="page" :total="tableRows.length" /></section></div></template>